194→
195→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
196→  const isInAnswerPhase = message.currentPhase === 'answer';
197→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
198→
199→  const hasCharts = hasSegments && message.segments!.some(
200→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
201→  );
202→
203→  const answerBlockSegments = hasSegments
204→    ? message.segments!
205→        .filter((s) =>
206→          (s.type === 'answer' && s.text?.trim()) ||
207→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim() && !hasAnswer) ||
208→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
