287→              onClick={handleSaveEdit}
288→            >
289→              {t('saveResend')}
290→            </button>
291→            <button
292→              className="message-bubble__edit-btn"
293→              onClick={handleCancelEdit}
294→            >
295→              {t('cancel')}
296→            </button>
297→          </div>
298→        </div>
299→      ) : hasSegments ? (
300→        <div className="message-bubble__segments">
301→          {!questionSegments.some((s) => !s.userAnswer) && (
302→            <ThinkingBlock
303→              segments={message.segments!}
304→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
305→              isThinkingPhase={isThinkingPhase}
306→              isAgentStreaming={!!message.isStreaming}
307→              hasAnswer={hasAnswer}
308→            />
309→          )}
310→          {questionSegments.map((seg, i) => (
311→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
312→              <UserQuestion
313→                questionData={seg.questionData!}
314→                userAnswer={seg.userAnswer}
315→                userFreeText={seg.userFreeText}
316→              />
317→            </div>
318→          ))}
319→          {answerBlockSegments.length > 0 && (
320→            <div className="message-bubble__segment message-bubble__segment--answer">
321→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
322→              {answerBlockSegments.map((seg, i) => {
323→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
324→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
325→                  return (
326→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
327→                      {seg.type === 'tool' && seg.toolResult ? (
328→                        <InlineQueryResult result={seg.toolResult!} />
329→                      ) : seg.chart_spec ? (
330→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
331→                      ) : null}
332→                    </div>
333→                  );
334→                }
335→                // Text segment (answer or subagent_end without chart_spec)
336→                return (
337→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
338→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
339→                  </div>
340→                );
341→              })}
342→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
343→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
344→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
345→                return displayText?.trim() ? (
346→                  <div className="message-bubble__segment-content">
347→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
348→                  </div>
349→                ) : null;
350→              })()}
351→            </div>
352→          )}
353→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
354→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
355→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
356→            return displayText?.trim() ? (
357→              <div className="message-bubble__segment message-bubble__segment--answer">
358→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
359→                <div className="message-bubble__segment-content">
360→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
361→                </div>
362→              </div>
363→            ) : null;
364→          })()}
365→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
366→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
367→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
368→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
369→          })}
370→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
371→            <span className="message-bubble__typing">{t('thinking')}</span>
372→          )}
373→        </div>
374→      ) : (
375→        <>
376→          <div className="message-bubble__content">
377→            {message.content ? (
378→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
379→            ) : message.isStreaming ? (
380→              <span className="message-bubble__typing">{t('thinking')}</span>
381→            ) : null}
382→          </div>
383→          {message.toolCalls && message.toolCalls.length > 0 && (
384→            <div className="message-bubble__tools">
385→              {message.toolCalls.map((tc) => (
386→                <InlineQueryResult key={tc.toolCallId} result={tc} />
387→              ))}
388→            </div>
389→          )}
390→        </>
391→      )}
392→    </div>
393→  );
394→}
